"use client";

import * as React from "react";
import { Plus, Search } from "lucide-react";
import styles from "./portfolio.module.css";

const ALBUM_PLACEHOLDER = "/images/默认作品.png";

export interface MoveToDialogAlbum {
    id: string;
    name: string;
    thumbnailUrl: string;
    count: number;
}

interface MoveToDialogProps {
    open: boolean;
    onClose: () => void;
    onSave: (albumId: string) => void;
    albums: MoveToDialogAlbum[];
    onNewAlbum?: (album: MoveToDialogAlbum) => void;
}

export function MoveToDialog({ open, onClose, onSave, albums, onNewAlbum }: MoveToDialogProps) {
    const [search, setSearch] = React.useState("");
    const [selectedAlbumId, setSelectedAlbumId] = React.useState<string | null>(null);
    const [localAlbums, setLocalAlbums] = React.useState<MoveToDialogAlbum[]>(albums);
    const [isCreateDialogOpen, setIsCreateDialogOpen] = React.useState(false);
    const [newAlbumName, setNewAlbumName] = React.useState("");
    const [isCreating, setIsCreating] = React.useState(false);
    const [createError, setCreateError] = React.useState<string | null>(null);
    const createInputRef = React.useRef<HTMLInputElement>(null);
    const nameLength = newAlbumName.trim().length;

    React.useEffect(() => {
        setLocalAlbums(albums);
    }, [albums]);

    const filtered = React.useMemo(() => {
        if (!search.trim()) {
            return localAlbums;
        }
        return localAlbums.filter((album) => album.name.toLowerCase().includes(search.toLowerCase()));
    }, [localAlbums, search]);

    React.useEffect(() => {
        if (!open) {
            setSearch("");
            setSelectedAlbumId(null);
            setIsCreateDialogOpen(false);
            setNewAlbumName("");
            setCreateError(null);
        }
    }, [open]);

    React.useEffect(() => {
        if (isCreateDialogOpen) {
            createInputRef.current?.focus();
        }
    }, [isCreateDialogOpen]);

    const handleCreateAlbum = async () => {
        const name = newAlbumName.trim();
        if (!name || isCreating) return;

        setIsCreating(true);
        setCreateError(null);
        try {
            const response = await fetch("/api/albums", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name }),
            });
            const data = await response.json() as { ok?: boolean; error?: string; album?: MoveToDialogAlbum };
            if (!response.ok || !data.ok || !data.album) {
                throw new Error(data.error || "新建作品册失败");
            }
            const newAlbum = data.album;
            setLocalAlbums((prev) => [newAlbum, ...prev]);
            onNewAlbum?.(newAlbum);
            setIsCreateDialogOpen(false);
            setNewAlbumName("");
            setSelectedAlbumId(newAlbum.id);
        } catch (error) {
            setCreateError(error instanceof Error ? error.message : "新建失败");
        } finally {
            setIsCreating(false);
        }
    };

    if (!open) {
        return null;
    }

    return (
        <div
            className={styles.moveDialogOverlay}
            role="presentation"
            onClick={(event) => {
                if (event.target === event.currentTarget) {
                    onClose();
                }
            }}
        >
            <div
                className={styles.moveDialog}
                role="dialog"
                aria-modal="true"
                aria-label="移动至"
            >
                <div className={styles.moveDialogHeader}>
                    <span className={styles.moveDialogTitle}>移动至</span>
                    <button
                        type="button"
                        className={styles.moveDialogNewAlbumBtn}
                        onClick={() => {
                            setIsCreateDialogOpen(true);
                            setCreateError(null);
                        }}
                    >
                        <Plus size={13} />
                        新建作品册
                    </button>
                </div>

                <div className={styles.moveDialogSearchWrapper}>
                    <Search size={16} className={styles.moveDialogSearchIcon} />
                    <input
                        className={styles.moveDialogSearchInput}
                        placeholder="搜索作品册…"
                        value={search}
                        onChange={(event) => setSearch(event.target.value)}
                    />
                </div>

                <div className={styles.moveDialogList}>
                    {filtered.length > 0 ? filtered.map((album) => (
                        <div
                            key={album.id}
                            className={`${styles.moveDialogItem} ${selectedAlbumId === album.id ? styles.moveDialogItemSelected : ""}`}
                            role="button"
                            tabIndex={0}
                            onClick={() => setSelectedAlbumId(album.id)}
                            onKeyDown={(event) => {
                                if (event.key === "Enter" || event.key === " ") {
                                    event.preventDefault();
                                    setSelectedAlbumId(album.id);
                                }
                            }}
                        >
                            <div className={styles.moveDialogItemThumb}>
                                <img
                                    src={album.thumbnailUrl || ALBUM_PLACEHOLDER}
                                    alt=""
                                    onError={(event) => {
                                        const image = event.currentTarget;
                                        image.onerror = null;
                                        image.src = ALBUM_PLACEHOLDER;
                                    }}
                                />
                            </div>
                            <span className={styles.moveDialogItemName}>{album.name}</span>
                            <span className={styles.moveDialogItemCount}>{album.count}</span>
                        </div>
                    )) : (
                        <div className={styles.moveDialogEmptyState}>
                            <img src="/images/暂无内容.png" alt="暂无内容" className={styles.moveDialogEmptyStateImage} />
                            <span className={styles.moveDialogEmptyStateText}>暂无匹配的作品册</span>
                        </div>
                    )}
                </div>
                <div className={styles.moveDialogFooter}>
                    <button type="button" className={styles.moveDialogCancelBtn} onClick={onClose}>
                        取消
                    </button>
                    <button
                        type="button"
                        className={styles.moveDialogSaveBtn}
                        disabled={!selectedAlbumId}
                        onClick={() => {
                            if (selectedAlbumId) {
                                onSave(selectedAlbumId);
                            }
                        }}
                    >
                        保存
                    </button>
                </div>
            </div>

            {isCreateDialogOpen ? (
                <div
                    className={styles.moveDialogCreateOverlay}
                    role="presentation"
                    onClick={(event) => {
                        if (event.target === event.currentTarget) {
                            setIsCreateDialogOpen(false);
                            setNewAlbumName("");
                            setCreateError(null);
                        }
                    }}
                >
                    <div className={styles.moveDialogCreateModal} role="dialog" aria-modal="true" aria-label="新建作品册">
                        <div className={styles.moveDialogCreateHeader}>
                            <h2 className={styles.moveDialogCreateTitle}>新建作品册</h2>
                        </div>

                        <div className={styles.moveDialogCreateField}>
                            <label htmlFor="move-dialog-create-album-name" className={styles.moveDialogCreateLabel}>作品册名称</label>
                            <div className={styles.moveDialogCreateInputWrap}>
                                <input
                                    id="move-dialog-create-album-name"
                                    ref={createInputRef}
                                    className={styles.moveDialogCreateInput}
                                    placeholder="请输入"
                                    value={newAlbumName}
                                    maxLength={20}
                                    onChange={(event) => setNewAlbumName(event.target.value.slice(0, 20))}
                                    onKeyDown={(event) => {
                                        if (event.key === "Enter") { void handleCreateAlbum(); }
                                        if (event.key === "Escape") {
                                            setIsCreateDialogOpen(false);
                                            setNewAlbumName("");
                                            setCreateError(null);
                                        }
                                    }}
                                />
                                <span className={styles.moveDialogCreateCounter}>{nameLength}/20</span>
                            </div>
                        </div>

                        {createError ? <p className={styles.moveDialogCreateError}>{createError}</p> : null}

                        <div className={styles.moveDialogCreateFooter}>
                            <button
                                type="button"
                                className={styles.moveDialogCancelBtn}
                                onClick={() => {
                                    setIsCreateDialogOpen(false);
                                    setNewAlbumName("");
                                    setCreateError(null);
                                }}
                            >
                                取消
                            </button>
                            <button
                                type="button"
                                className={styles.moveDialogSaveBtn}
                                onClick={() => {
                                    void handleCreateAlbum();
                                }}
                                disabled={!newAlbumName.trim() || isCreating}
                            >
                                {isCreating ? "保存中..." : "确定"}
                            </button>
                        </div>
                    </div>
                </div>
            ) : null}
        </div>
    );
}