/* ─── Types ─── */
type MediaFilter = "all" | "image" | "video" | "model";

interface IPortfolioPageProps {
    albumName?: string;
    albumId?: string;
    backHref?: string;
}

interface IPortfolioItem {
    id: string;
    name: string;
    url: string;
    mediaType: MediaPreviewKind;
    /** thumbnail URL (same as url for images) */
    thumbnailUrl: string;
    createdAt: Date;
    promptText?: string;
    workflowType?: "text" | "line" | "magic" | null;
}

const FILTER_TABS: Array<{ id: MediaFilter; label: string }> = [
    { id: "all", label: "全部作品" },
    { id: "image", label: "图片生成" },
    { id: "video", label: "视频生成" },
    { id: "model", label: "3D模型生成" },
];

const IMAGE_ACTIONS = ["再次生成", "重新描述", "魔法改图", "生成视频", "生成模型"];
const VIDEO_ACTIONS = ["再次生成", "重新描述"];
const HANDOFF_STORAGE_KEY = "studio:pending-media-handoff";

interface IAssetApiItem {
    id: number;
    title: string | null;
    promptText: string | null;
    fileName: string;
    relativePath: string;
    mediaType: Exclude<MediaFilter, "all">;
    workflowType: "text" | "line" | "magic" | null;
    thumbnailPath: string | null;
    createdAt: string;
}

function getAssetFileUrl(relativePath: string) {
    return `/api/assets/file?path=${encodeURIComponent(relativePath)}`;
}

function mapAssetToPortfolioItem(item: IAssetApiItem): IPortfolioItem {
    const url = getAssetFileUrl(item.relativePath);
    const thumbnailUrl = item.thumbnailPath
        ? getAssetFileUrl(item.thumbnailPath)
        : item.mediaType === "model"
            ? "/images/homeicon3.png"
            : url;

    return {
        id: String(item.id),
        name: item.title?.trim() || item.fileName,
        url,
        thumbnailUrl,
        mediaType: item.mediaType,
        createdAt: new Date(item.createdAt),
        promptText: item.promptText || undefined,
        workflowType: item.workflowType,
    };
}

/* ────────────────────────────────────────────
 *  PortfolioPage (main)
 * ──────────────────────────────────────────── */
export default function PortfolioPage({
    albumName = "默认作品",
    albumId = "default",
    backHref = "/portfolio",
}: IPortfolioPageProps) {
    React.useEffect(() => {
        void import("@google/model-viewer");
    }, []);

    const router = useRouter();
    /* state */
    const [items, setItems] = React.useState<IPortfolioItem[]>([]);
    const [allAlbums, setAllAlbums] = React.useState<MoveToDialogAlbum[]>([]);
    const [activeFilter, setActiveFilter] = React.useState<MediaFilter>("all");
    const [searchQuery, setSearchQuery] = React.useState("");
    const [batchMode, setBatchMode] = React.useState(false);
    const [selectedIds, setSelectedIds] = React.useState<Set<string>>(new Set());
    const [moveDialogOpen, setMoveDialogOpen] = React.useState(false);
    const [isLoading, setIsLoading] = React.useState(true);
    const [loadError, setLoadError] = React.useState<string | null>(null);
    const [previewItem, setPreviewItem] = React.useState<IPortfolioItem | null>(null);
    const [actionHint, setActionHint] = React.useState<string | null>(null);
    const actionHintTimerRef = React.useRef<number | null>(null);

    const currentPreviewItem = previewItem;

    const showActionHint = React.useCallback((message: string) => {
        setActionHint(message);
        if (actionHintTimerRef.current) {
            window.clearTimeout(actionHintTimerRef.current);
        }
        actionHintTimerRef.current = window.setTimeout(() => {
            setActionHint((current) => (current === message ? null : current));
        }, 1800);
    }, []);

    React.useEffect(() => {
        return () => {
            if (actionHintTimerRef.current) {
                window.clearTimeout(actionHintTimerRef.current);
            }
        };
    }, []);

    React.useEffect(() => {
        const controller = new AbortController();

        const loadAssets = async () => {
            setIsLoading(true);
            setLoadError(null);

            try {
                const params = new URLSearchParams();
                if (activeFilter !== "all") {
                    params.set("mediaType", activeFilter);
                }
                if (searchQuery.trim()) {
                    params.set("search", searchQuery.trim());
                }
                if (albumId) {
                    params.set("albumId", albumId);
                }

                const query = params.toString();
                const response = await fetch(`/api/assets${query ? `?${query}` : ""}`, {
                    signal: controller.signal,
                });

                if (!response.ok) {
                    throw new Error("加载作品册失败");
                }

                const data = await response.json() as { assets?: IAssetApiItem[] };
                setItems((data.assets || []).map(mapAssetToPortfolioItem));
            } catch (error) {
                if (controller.signal.aborted) {
                    return;
                }
                setLoadError(error instanceof Error ? error.message : "加载作品册失败");
                setItems([]);
            } finally {
                if (!controller.signal.aborted) {
                    setIsLoading(false);
                }
            }
        };

        void loadAssets();

        return () => {
            controller.abort();
        };
    }, [activeFilter, searchQuery, albumId]);

    /* 加载所有作品册 */
    React.useEffect(() => {
        const loadAlbums = async () => {
            try {
                const response = await fetch("/api/albums");
                let allAlbumsList: MoveToDialogAlbum[] = [];

                if (response.ok) {
                    const data = await response.json() as { albums?: MoveToDialogAlbum[] };
                    allAlbumsList = data.albums || [];
                }

                // 确保默认作品显示在列表中
                const defaultAlbum: MoveToDialogAlbum = {
                    id: "default",
                    name: albumName,
                    thumbnailUrl: items[0]?.thumbnailUrl || "/images/默认作品.png",
                    count: items.length,
                };

                // 如果不存在默认作品，添加它；否则更新计数
                const hasDefault = allAlbumsList.some((a) => a.id === "default");
                if (!hasDefault) {
                    allAlbumsList.unshift(defaultAlbum);
                } else {
                    allAlbumsList = allAlbumsList.map((a) =>
                        a.id === "default" ? { ...a, count: items.length } : a
                    );
                }

                setAllAlbums(allAlbumsList);
            } catch (error) {
                console.error("加载作品册失败:", error);
                // 至少显示默认作品
                setAllAlbums([
                    {
                        id: "default",
                        name: albumName,
                        thumbnailUrl: items[0]?.thumbnailUrl || "/images/默认作品.png",
                        count: items.length,
                    },
                ]);
            }
        };

        void loadAlbums();
    }, [albumName, items]);

    /* derived */
    const filteredItems = items;
    const albums = allAlbums;

    const handleToggleSelect = (id: string) => {
        setSelectedIds((prev) => {
            const next = new Set(prev);
            if (next.has(id)) {
                next.delete(id);
            } else {
                next.add(id);
            }
            return next;
        });
    };

    const handleSelectAll = () => {
        if (selectedIds.size === filteredItems.length) {
            setSelectedIds(new Set());
        } else {
            setSelectedIds(new Set(filteredItems.map((i) => i.id)));
        }
    };

    const handleExitBatchMode = () => {
        setBatchMode(false);
        setSelectedIds(new Set());
    };

    const handleMoveSave = React.useCallback(async (targetAlbumId: string) => {
        if (selectedIds.size === 0) return;
        if (targetAlbumId === albumId) {
            alert("不能移动到当前作品册");
            return;
        }

        const itemIds = Array.from(selectedIds);
        try {
            const response = await fetch("/api/assets/batch-move", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ ids: itemIds, albumId: targetAlbumId }),
            });

            if (!response.ok) {
                const result = await response.json().catch(() => null) as { error?: string } | null;
                throw new Error(result?.error || "移动失败");
            }

            // 移动成功后，从当前列表中移除这些项
            setItems((prev) => prev.filter((item) => !selectedIds.has(item.id)));
            setSelectedIds(new Set());
            setMoveDialogOpen(false);
            setBatchMode(false);
        } catch (error) {
            console.error("移动错误:", error);
            alert(error instanceof Error ? error.message : "移动失败");
        }
    }, [albumId, selectedIds]);

    const handleDelete = React.useCallback(async () => {
        if (selectedIds.size === 0) return;

        if (!confirm("确定要删除选中的作品吗？此操作不可撤销。")) {
            return;
        }

        const itemIds = Array.from(selectedIds);
        try {
            const response = await fetch("/api/assets/batch-delete", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ ids: itemIds }),
            });

            if (!response.ok) {
                throw new Error("删除失败");
            }

            // 删除成功后，从列表中移除这些项
            setItems((prev) => prev.filter((item) => !selectedIds.has(item.id)));
            setSelectedIds(new Set());
            setBatchMode(false);
        } catch (error) {
            console.error("删除错误:", error);
            alert(error instanceof Error ? error.message : "删除失败");
        }
    }, [selectedIds]);

    const handleBatchDownload = () => {
        // Download all selected items
        selectedIds.forEach((id) => {
            const item = filteredItems.find((i) => i.id === id);
            if (item) {
                const link = document.createElement("a");
                link.href = item.url;
                link.download = item.name || `portfolio-${item.id}`;
                link.click();
            }
        });
    };

    const handleCopyPrompt = React.useCallback(async () => {
        if (!currentPreviewItem?.promptText) {
            showActionHint("暂无可复制描述");
            return;
        }
        try {
            await navigator.clipboard.writeText(currentPreviewItem.promptText);
            showActionHint("描述已复制");
        } catch {
            showActionHint("复制失败，请手动复制");
        }
    }, [currentPreviewItem, showActionHint]);

    const handleDownloadItem = React.useCallback(() => {
        if (!currentPreviewItem) return;
        const link = document.createElement("a");
        link.href = currentPreviewItem.url;
        link.download = currentPreviewItem.name || "portfolio-item";
        link.click();
        showActionHint("已触发下载");
    }, [currentPreviewItem, showActionHint]);

    const fileUrlToDataUrl = React.useCallback(async (url: string): Promise<{ dataUrl: string; fileType: string }> => {
        const res = await fetch(url);
        if (!res.ok) {
            throw new Error("读取作品失败");
        }
        const blob = await res.blob();

        const dataUrl = await new Promise<string>((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(String(reader.result || ""));
            reader.onerror = () => reject(new Error("读取作品失败"));
            reader.readAsDataURL(blob);
        });

        return {
            dataUrl,
            fileType: blob.type || "application/octet-stream",
        };
    }, []);

    const navigateWithHandoff = React.useCallback(async (
        targetMode: "image" | "video" | "model",
        options?: { imageWorkflow?: "text" | "line" | "magic" },
    ) => {
        const item = currentPreviewItem;
        if (item) {
            try {
                const { dataUrl, fileType } = await fileUrlToDataUrl(item.url);
                window.sessionStorage.setItem(HANDOFF_STORAGE_KEY, JSON.stringify({
                    targetMode,
                    imageWorkflow: options?.imageWorkflow,
                    promptText: item.promptText || "",
                    fileName: item.name || "portfolio-output",
                    fileType,
                    dataUrl,
                }));
            } catch {
                // Navigation still works without handoff payload.
            }
        }

        setPreviewItem(null);

        if (targetMode === "image" && options?.imageWorkflow) {
            router.push(`/image?tab=${options.imageWorkflow}`);
            return;
        }
        router.push(`/${targetMode}`);
    }, [currentPreviewItem, fileUrlToDataUrl, router]);

    const handleImagePreviewAction = React.useCallback((label: string) => {
        if (label === "再次生成" || label === "重新描述") {
            const workflow = currentPreviewItem?.workflowType || "text";
            void navigateWithHandoff("image", { imageWorkflow: workflow === "line" || workflow === "magic" ? workflow : "text" });
            return;
        }
        if (label === "魔法改图") {
            void navigateWithHandoff("image", { imageWorkflow: "magic" });
            return;
        }
        if (label === "生成视频") {
            void navigateWithHandoff("video");
            return;
        }
        if (label === "生成模型") {
            void navigateWithHandoff("model");
        }
    }, [currentPreviewItem?.workflowType, navigateWithHandoff]);

    const handleVideoModelPreviewAction = React.useCallback((label: string) => {
        if (label === "再次生成" || label === "重新描述") {
            const mode = currentPreviewItem?.mediaType === "model" ? "model" : "video";
            void navigateWithHandoff(mode);
        }
    }, [currentPreviewItem?.mediaType, navigateWithHandoff]);

    /* search result label */
    const showSearchResult = searchQuery.trim().length > 0;

    return (
        <main className={styles.portfolioPage}>
            <PortfolioPageBackground />
            {/* ─── Top bar ─── */}
            <div className={styles.topBar}>
                <Link href={backHref} className={styles.backButton} aria-label="返回作品册">
                    <ChevronLeft size={22} />
                </Link>
                <div className={styles.searchWrapper}>
                    <Search size={16} className={styles.searchIcon} />
                    <input
                        className={styles.searchInput}
                        placeholder="输入作品名称搜索..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
                <div className={styles.brandWrap}>
                    <PendingAsset
                        src={BRAND_LOGO_PATH}
                        alt="飞思玖·璇玑AI"
                        className={styles.brandLogoAsset}
                        imageClassName={styles.brandLogoImage}
                        fit="contain"
                    />
                </div>
            </div>

            {/* ─── Content ─── */}
            <div className={styles.contentArea}>
                <div className={styles.contentHeaderArea}>
                    {/* section header */}
                    <div className={styles.sectionHeader}>
                        <h2 className={styles.sectionTitle}>
                            {batchMode ? "所有作品" : albumName}
                        </h2>

                        <div className={styles.filterTabs}>
                            {FILTER_TABS.map((tab) => (
                                <button
                                    key={tab.id}
                                    type="button"
                                    className={`${styles.filterTab} ${activeFilter === tab.id ? styles.filterTabActive : ""}`}
                                    onClick={() => setActiveFilter(tab.id)}
                                >
                                    <span>{tab.label}</span>
                                </button>
                            ))}
                        </div>

                        <button
                            type="button"
                            className={`${styles.manageButton} ${batchMode ? styles.manageButtonActive : ""}`}
                            onClick={() => {
                                if (batchMode) {
                                    handleExitBatchMode();
                                } else {
                                    setBatchMode(true);
                                }
                            }}
                        >
                            <Settings2 size={22} />
                            <span>{batchMode ? "退出管理" : "批量管理"}</span>
                        </button>
                    </div>
                </div>

                <div className={styles.contentListArea}>
                    {/* search result label */}
                    {showSearchResult && (
                        <p className={styles.searchResult}>
                            &ldquo;{searchQuery}&rdquo; ({filteredItems.length})
                        </p>
                    )}

                    {/* ─── Gallery grid / Empty state ─── */}
                    {isLoading ? (
                        <div className={styles.emptyState}>
                            <img
                                src="/images/clear.png"
                                alt="加载中"
                                className={styles.emptyStateIcon}
                            />
                            <span className={styles.emptyStateText}>加载中...</span>
                        </div>
                    ) : filteredItems.length > 0 ? (
                        <div className={styles.galleryGrid}>
                            {filteredItems.map((item) => (
                                <div
                                    key={item.id}
                                    className={styles.galleryCard}
                                    role="button"
                                    tabIndex={0}
                                    onClick={() => {
                                        if (!batchMode) {
                                            setPreviewItem(item);
                                        }
                                    }}
                                    onKeyDown={(e) => {
                                        if (!batchMode && (e.key === "Enter" || e.key === " ")) {
                                            e.preventDefault();
                                            setPreviewItem(item);
                                        }
                                    }}
                                >
                                    {item.mediaType === "video" ? (
                                        <>
                                            <video src={item.url} className={styles.cardVideo} muted playsInline preload="metadata" />
                                            <div className={styles.videoOverlay} />
                                        </>
                                    ) : (
                                        <img src={item.thumbnailUrl} alt={item.name} />
                                    )}

                                    {item.mediaType === "video" && (
                                        <div className={styles.videoPlayIcon}>
                                            <Play size={16} fill="#fff" />
                                        </div>
                                    )}

                                    <span className={styles.cardLabel}>{item.name}</span>

                                    {batchMode && (
                                        <div
                                            role="checkbox"
                                            aria-checked={selectedIds.has(item.id)}
                                            tabIndex={0}
                                            className={`${styles.selectionCheckbox} ${selectedIds.has(item.id) ? styles.selectionCheckboxSelected : ""}`}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                handleToggleSelect(item.id);
                                            }}
                                            onKeyDown={(e) => {
                                                if (e.key === "Enter" || e.key === " ") {
                                                    e.preventDefault();
                                                    handleToggleSelect(item.id);
                                                }
                                            }}
                                        >
                                            {selectedIds.has(item.id) && <Check size={14} strokeWidth={3} color="#fff" />}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className={styles.emptyState}>
                            <img
                                src="/images/暂无内容.png"
                                alt="暂无内容"
                                className={styles.emptyStateIcon}
                            />
                            <span className={styles.emptyStateText}>{loadError || "暂未找到相关内容"}</span>
                        </div>
                    )}
                </div>
            </div>

            {/* ─── Batch action bar ─── */}
            {batchMode && (
                <div className={styles.batchActionBar}>
                    <button
                        type="button"
                        className={styles.selectAllCheckbox}
                        onClick={handleSelectAll}
                    >
                        <div
                            className={`${styles.selectionCheckbox} ${selectedIds.size === filteredItems.length && filteredItems.length > 0 ? styles.selectionCheckboxSelected : ""}`}
                            style={{ position: "static", width: 18, height: 18 }}
                        >
                            {selectedIds.size === filteredItems.length && filteredItems.length > 0 && (
                                <Check size={12} color="#fff" />
                            )}
                        </div>
                        <span>全选（已选{selectedIds.size}个）</span>
                    </button>

                    <button
                        type="button"
                        className={`${styles.batchButton} ${styles.batchButtonPrimary}`}
                        onClick={handleBatchDownload}
                    >
                        存储
                    </button>

                    <button
                        type="button"
                        className={`${styles.batchButton} ${styles.batchButtonDefault}`}
                        onClick={handleDelete}
                    >
                        删除
                    </button>

                    <button
                        type="button"
                        className={`${styles.batchButton} ${styles.batchMoveButton}`}
                        onClick={() => setMoveDialogOpen(true)}
                    >
                        <img src="/images/文件夹.png" width={22} height={22} alt="" />
                        移动至
                    </button>

                    <button
                        type="button"
                        className={styles.batchCloseButton}
                        onClick={handleExitBatchMode}
                        aria-label="退出管理"
                    >
                        <X size={22} />
                    </button>
                </div>
            )}

            {/* ─── Move-to dialog ─── */}
            <MoveToDialog
                open={moveDialogOpen}
                onClose={() => setMoveDialogOpen(false)}
                onSave={handleMoveSave}
                albums={albums} onNewAlbum={(album) => setAllAlbums((prev) => [album, ...prev])} />

            {/* ─── Preview Modal ─── */}
            <MediaPreviewModal
                open={currentPreviewItem !== null}
                kind={currentPreviewItem?.mediaType || "image"}
                mediaUrl={currentPreviewItem?.url}
                mediaName={currentPreviewItem?.name}
                promptText={currentPreviewItem?.promptText}
                thumbUrl={currentPreviewItem?.thumbnailUrl}
                actionHint={actionHint}
                onClose={() => setPreviewItem(null)}
                onCopyPrompt={() => void handleCopyPrompt()}
                onSave={() => void handleDownloadItem()}
                themeStyle={currentPreviewItem?.mediaType === "model" ? { background: "linear-gradient(180deg, #f4f3fd 0%, #f8f8fb 100%)" } : undefined}
                imageActions={[]}
                sideActions={currentPreviewItem?.mediaType === "image" ? IMAGE_ACTIONS : currentPreviewItem?.mediaType === "video" ? VIDEO_ACTIONS : []}
                onImageAction={handleImagePreviewAction}
                onSideAction={handleVideoModelPreviewAction}
            />
        </main>
    );
}
